p.yx = product.xy;polar = vec2( atan(p.x,p.z)*q1,atan(p.y,length(p.xz))*q1 * 4.0 + 0.5);
// End //
vec3 tex= texture(sampler_jiansimanjuntak_nebula002,polar).xyz;
tex*= tex;
// shadow:
float L2 = lum(GetBlur2(uv - 0.01));
ret = mix(ret, tex, use_tex);
ret *= 2.00; //gamma
// Thank you for edited by Jian Simanjuntak //
}

