product = vec2( factorA.x*factorB.x - factorA.y*factorB.y,factorA.x*factorB.y + factorA.y*factorB.x);
p.zy = product.xy;factorA = p.zx;factorB = vec2(q4,q5);
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y,factorA.x*factorB.y + factorA.y*factorB.x);
p.zx = product.xy;factorA = p.yx;factorB = vec2(q6,q7);
product = vec2( factorA.x*factorB.x - factorA.y*factorB.y, factorA.x*factorB.y + factorA.y*factorB.x);
p.yx = product.xy;polar = vec2( atan(p.x,p.z)*q1,atan(p.y,length(p.xz))*q1 * 4.0 + 0.5);
// End //
vec3 tex= texture(sampler_jiansimanjuntak_nebula002,polar).xyz;
tex*= tex;
// shadow:
float L2 = lum(GetBlur2(uv - 0.01));
ret = mix(ret, tex, use_tex);
